command:
if (!game.user.isGM) return ui.notifications.warn('Grant XP is GM-only.');

const units = (canvas.tokens?.controlled ?? []).filter(token => token.actor?.type === 'Character');
if (units.length !== 1) return ui.notifications.warn('Select exactly one unit.');

const unit = units[0].actor;
const PROGRESSING_ROLES = ['Lord', 'Retainer'];
const role = unit.system.faction?.role ?? 'Neutral';
if (!PROGRESSING_ROLES.includes(role)) {
  return ui.notifications.warn(`${unit.name} is ${role}, which does not gain XP.`);
}

const MAX_LEVEL = 30;
const XP_PER_LEVEL = 100;
const progression = unit.system.progression ?? {};
const level = Number(progression.level) || 1;
const exp = Number(progression.experience) || 0;

const amount = await foundry.applications.api.DialogV2.wait({
  window: { title: `Grant XP — ${unit.name}` },
  classes: ['emblem-rpg', 'dialog-editor'],
  position: { width: 400 },
  content: `
    <div class="ed-container">
      <div class="ed-section ed-section--highlight">
        <p class="ed-description">Level ${level} &mdash; ${exp} / ${XP_PER_LEVEL} XP</p>
      </div>
      <div class="ed-section">
        <label class="ed-label" for="emblem-xp-amount">XP to grant</label>
        <input id="emblem-xp-amount" class="ed-input" type="number" name="xp" min="1" step="1" value="10" autofocus />
      </div>
      ${level >= MAX_LEVEL ? '<div class="ed-section"><p class="ed-description">This unit is at max level; XP will be discarded.</p></div>' : ''}
    </div>`,
  buttons: [
    {
      action: 'grant',
      label: 'Grant XP',
      icon: 'fas fa-star',
      default: true,
      callback: (event, button) => Number(button.form.elements.xp.value)
    },
    { action: 'cancel', label: 'Cancel', callback: () => null }
  ],
  rejectClose: false
});

if (amount === null || amount === undefined || typeof amount !== 'number') return;
if (!Number.isFinite(amount) || amount <= 0) return ui.notifications.warn('Enter a positive XP amount.');

const before = { level, exp };
const result = await game.emblemRpg.api.character.progression.grantExperience({
  actorUuid: unit.uuid,
  experience: Math.floor(amount)
});
if (!result.ok) return;
const after = {
  level: Number(unit.system.progression?.level) || before.level,
  exp: Number(unit.system.progression?.experience) || 0
};

console.log(`emblem-rpg | Grant XP — ${unit.name} +${Math.floor(amount)} XP`, { before, after, result });
